/*
 * A257987  Sequence (a(n)) generated by Rule 3 (in Comments) with a(1) = 2
 *          and d(1) = 2.
 * https://oeis.org/A257987
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 168, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   int64_in_array
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence (a(n)) generated by Rule 3:  a(1)=2, d(1)=2.
   The function implements the iterative construction described in the
   OEIS entry and memoises all previously computed terms so that
   calls in any order remain efficient.  */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include "../utils/int64_in_array.h"

/* Helper to enlarge a buffer of type T up to at least 'need'.
   The arrow (&) cast is required for C++ compilation. */
#define ENLARGE_BUF(buf, cap, need, type)                     \
    do {                                                     \
        if ((cap) > (need)) break;                           \
        size_t newcap = (cap) ? (cap) * 2 : 128;              \
        while (newcap <= (need)) newcap <<= 1;                \
        (buf) = (type*)realloc((buf), newcap * sizeof(type));\
        if (!(buf)) abort();                                 \
        (cap) = newcap;                                      \
    } while (0)

/* Test whether val is present in an array of seq_t values. */
static bool seq_in_array(const seq_t *arr, size_t cnt, seq_t val) {
    for (size_t i = 0; i < cnt; i++)
        if (arr[i] == val) return true;
    return false;
}

/* ------------------------------------------------------------------ */

seq_t a(idx_t n) {
    /* Static state: caches of computed a(k) and d(k). */
    static seq_t *a_vals   = NULL;
    static size_t a_cap    = 0;
    static size_t a_cnt    = 0;

    static int64_t *d_vals = NULL;   /* signed d(k) values */
    static size_t d_cap    = 0;
    static size_t d_cnt    = 0;

    /* Initialise on first call. */
    if (a_cnt == 0) {
        /* a(1) = 2, d(1) = 2 */
        a_cap = 128;
        a_vals = (seq_t*)malloc(a_cap * sizeof(seq_t));
        if (!a_vals) abort();
        a_vals[0] = 2;
        a_cnt    = 1;

        d_cap = 128;
        d_vals = (int64_t*)malloc(d_cap * sizeof(int64_t));
        if (!d_vals) abort();
        d_vals[0] = 2;
        d_cnt    = 1;
    }

    /* Generate terms until we have at least n of them. */
    while (a_cnt < n) {
        seq_t ak = a_vals[a_cnt - 1];

        /* Step 1: look for a negative h satisfying the conditions. */
        bool found = false;
        int64_t h = 0;
        int64_t h_start = (int64_t)1 - (int64_t)ak + 1;   /* first candidate > 1-ak */

        for (h = h_start; h < 0; h++) {
            /* h must not be in D so far. */
            if (int64_in_array(d_vals, d_cnt, h)) continue;

            /* a(k) + h must not be in A. */
            seq_t target = ak - (seq_t)(-h);   /* a(k)+h with negative h */
            if (seq_in_array(a_vals, a_cnt, target)) continue;

            /* Found a valid h. */
            found = true;
            break;
        }

        seq_t a_next;
        int64_t d_next;

        if (found) {
            /* Step 1 succeeded. */
            d_next = h;                     /* h is negative */
            a_next = ak + (seq_t)h;         /* target from above */
        } else {
            /* Step 2: find the least positive h not in D with a(k)-h not in A. */
            int64_t cand = 1;
            for (;;) {
                if (int64_in_array(d_vals, d_cnt, cand)) { cand++; continue; }
                seq_t target = ak - (seq_t)cand;
                if (seq_in_array(a_vals, a_cnt, target)) { cand++; continue; }
                h      = cand;
                d_next = cand;
                a_next = ak + (seq_t)cand;
                break;
            }
        }

        /* Append new values to the caches. */
        ENLARGE_BUF(a_vals, a_cap, a_cnt, seq_t);
        a_vals[a_cnt] = a_next;
        a_cnt++;

        ENLARGE_BUF(d_vals, d_cap, d_cnt, int64_t);
        d_vals[d_cnt] = d_next;
        d_cnt++;
    }

    return a_vals[n - 1];
}
